#!/usr/bin/env python3

import os
import re
from flask import Flask, render_template, send_from_directory, abort
from werkzeug.utils import secure_filename

# Enable safe mode
SAFE_MODE = True

app = Flask(__name__)

# Define approved CSS classes (whitelist)
APPROVED_CSS_CLASSES = {
    'container', 'row', 'col', 'btn', 'btn-primary', 'btn-secondary', 
    'card', 'card-body', 'table', 'alert', 'alert-info', 'alert-danger',
    'form-control', 'navbar', 'navbar-brand', 'nav', 'nav-item', 'nav-link',
    'jumbotron', 'display-4', 'lead', 'text-center', 'mt-3', 'mb-3', 'p-3'
}

def validate_html_css_content(content):
    """Validate that HTML content only contains approved CSS classes"""
    # Extract all class attributes from HTML tags
    class_pattern = r'class=["\']([^"\']*)["\']'
    matches = re.findall(class_pattern, content)

    # Check each found class attribute
    for class_attr in matches:
        classes = class_attr.split()
        for css_class in classes:
            # Remove any potential malicious characters
            clean_class = re.sub(r'[^\w\-]', '', css_class)
            if clean_class not in APPROVED_CSS_CLASSES:
                return False, f"Unauthorized CSS class detected: {css_class}"

    return True, "Validation passed"

def is_safe_path(path):
    """Check if path is safe to serve"""
    # Resolve the absolute path
    safe_path = os.path.abspath(path)
    base_path = os.path.abspath('.')

    # Ensure the path is within our workspace
    return safe_path.startswith(base_path)

@app.route('/')
